// Some portions generated by Codex
import assert from 'node:assert/strict';
import test from 'node:test';
import {placeFan, unitShapes} from '../../../main/frontend/graph-explorer/graph-layout-fans.ts';
import {segmentHitsBox} from '../../../main/frontend/graph-explorer/graph-layout-stress.ts';
import {referencePlaceFan, referenceUnitShapes} from './support/reference-fans.ts';

const SPACING = {edgeLength: 90, clearX: 48, clearY: 36, aspectRatio: 1.6};
const box = (x, y, width = 220, height = 46) => ({
  left: x - width / 2, right: x + width / 2, top: y - height / 2, bottom: y + height / 2,
});

function request(count, overrides = {}, nested = false, reference = false) {
  const units = Array.from({length: count}, (_, i) => i + 1);
  const children = Array.from({length: count + 7}, () => []);
  children[0] = units;
  if (nested) {
    children[1] = [count + 1, count + 2];
    children[count + 1] = [count + 3];
    children[2] = [count + 4];
  }
  const spacing = {...SPACING, ...overrides.spacing};
  const size = card => ({width: 180 + card % 5 * 20, height: 40 + card % 3 * 6});
  const shape = (reference ? referenceUnitShapes : unitShapes)(children, size, spacing);
  return {halfWidth: 110, halfHeight: 23, units, shape, spread: true, ...overrides, spacing};
}

// Compare every original Number (including -0), every unit/offset order and the chosen ring geometry.
function orderedFan(fan) {
  return {
    extents: fan.extents, inner: fan.inner, ring: fan.ring,
    placements: fan.placements.map(({card, side, x, y, shape}) => ({
      card, side, x, y, extents: shape.extents, offsets: [...shape.offsets],
    })),
  };
}

function sameFan(count, overrides = {}, nested = false) {
  const before = structuredClone(overrides);
  const actual = placeFan(request(count, overrides, nested));
  const expected = referencePlaceFan(request(count, structuredClone(overrides), nested, true));
  assert.deepEqual(orderedFan(actual), orderedFan(expected), 'all coordinates and candidate/tie ordering match the scan oracle');
  assert.deepEqual(overrides, before, 'obstacle geometry and spacing remain owned by the caller');
  assert.deepEqual(actual.placements.map(p => p.card), Array.from({length: count}, (_, i) => i + 1));
  return actual;
}

test('fan obstacle searches preserve ellipses, rectangular rings and nested unit shapes exactly', () => {
  for (const [count, nested] of [[5, false], [12, false], [44, false], [3, true]]) {
    const clean = sameFan(count, {}, nested);
    assert.equal(Boolean(clean.ring), nested || count > 8, 'both the ellipse and ring paths are characterized');
    sameFan(count, {
      spread: false, facing: 2, span: 0.75, direction: Math.PI * 0.83,
      obstacles: {
        boxes: [box(-280, -160), box(540, 260), box(-1800, 900, 1800, 48)],
        areas: [box(360, -300, 420, 160)],
        segments: [[-900, -170, 1400, -170], [80, -900, 80, -520], [-400, 440, 600, 800]],
        directions: [0.12, -1.3],
      },
    }, nested);
  }
});

