test('unit segment searches preserve tangencies, reversed endpoints and near-parallel clipping exactly', () => {
  const clean = sameFan(12);
  const first = clean.placements[0], e = first.shape.extents;
  const left = first.x - e.left - 10, right = first.x + e.right + 10;
  const top = first.y - e.top - 10, bottom = first.y + e.bottom + 10;
  const distant = Array.from({length: 32}, (_, i) => [-12000 + i * 200, -9000, -11900 + i * 200, -8500]);
  for (const delta of [-1e-10, 0, 1e-10]) {
    const segments = [
      ...distant,
      [left + delta, top - 500, left + delta, bottom + 500],
      [right + 500, bottom + delta, left - 500, bottom + delta],
      [right + delta, top, right + delta, top],
      [left - 500, top - delta, left - 500 + 1e-13, bottom + 500],
    ];
    sameFan(12, {obstacles: {boxes: [], segments, shadows: true}});
    sameFan(12, {obstacles: {boxes: [], segments: segments.slice().reverse(), shadows: true}});
  }
});

