test('unit segment searches retain scan behavior for inverted and nonfinite unit bounds', () => {
  const obstacles = {boxes: [], segments: [[-12000, -9000, -11900, -8500], [12000, 8500, 12100, 9000]], shadows: true};
  for (const extents of [{left: -400, right: -400}, {left: NaN}, {left: Infinity}]) {
    const make = reference => {
      const result = request(9, {obstacles: structuredClone(obstacles)}, false, reference);
      const shape = result.shape;
      // Leave the along-side extent finite so the ring still reaches clipping with an unusual query box.
      result.shape = (card, side) => {
        const unit = shape(card, side);
        return side === 0 ? {...unit, extents: {...unit.extents, ...extents}} : unit;
      };
      return result;
    };
    const actual = placeFan(make(false)), expected = referencePlaceFan(make(true));
    assert.deepEqual(orderedFan(actual), orderedFan(expected), 'unusual query bounds preserve all original Numbers and order');
    assert.equal(actual.placements.length, 9);
  }
});

test('unit segment broad phase retains rounded endpoint hits beyond very large finite query bounds', () => {
  for (const axis of ['x', 'y']) {
    const overrides = axis === 'x' ? {halfWidth: 2 ** 53} : {halfHeight: 2 ** 53};
    const clean = sameFan(9, overrides), first = clean.placements[0], e = first.shape.extents;
    assert.equal(clean.ring, true, 'nine units enter the prepared ring search');
    const bounds = [first.x - e.left - 10, first.y - e.top - 10,
      first.x + e.right + 10, first.y + e.bottom + 10];
    assert.ok(bounds.every(Number.isFinite));
    const [left, top, right, bottom] = bounds;
    const x = (left + right) / 2, y = (top + bottom) / 2;
    const segment = axis === 'x' ? [-(2 ** 80), y, left - 2, y] : [x, 2 ** 80, x, bottom + 2];
    assert.ok(axis === 'x' ? segment[2] < left : segment[3] > bottom,
      'the endpoint AABB is strictly outside the query');
    assert.equal(segmentHitsBox(...segment, ...bounds), true,
      'finite endpoint subtraction/division rounds the clipping parameter onto one');
    // Segment zero misses, so a real ring trial must prepare/query the production segment broad phase. An exact
    // AABB rejection would lose the rounded hit above; compare the entire resulting fan with the unindexed oracle.
    for (const endpoints of [segment, [segment[2], segment[3], segment[0], segment[1]]]) {
      sameFan(9, {...overrides, obstacles: {
        boxes: [], segments: [[1000000, 1000000, 1000001, 1000001], endpoints], shadows: true,
      }});
    }
  }
});

