test('fan unit clips and shadow retries preserve explicit and fallback arrow ports', () => {
  for (const nested of [false, true]) for (const shadows of [false, true]) {
    const make = reference => {
      const result = request(9, {spread: false, facing: 0, span: 0.5, obstacles: {
        boxes: [box(150, -50, 10, 10), box(-400, 250, 30, 20)],
        segments: [[300, -1000, 300, 1000], [-200, 250, 800, 250]], shadows,
      }}, nested, reference);
      const shape = result.shape;
      result.shape = (card, side) => {
        const original = shape(card, side), offsets = new Map(original.offsets);
        if (card % 2 === 0) offsets.delete(-1);
        return {...original, offsets};
      };
      return result;
    };
    const actual = placeFan(make(false)), expected = referencePlaceFan(make(true));
    assert.deepEqual(orderedFan(actual), orderedFan(expected),
      'unit clipping, shadow early-outs and both card-half representations preserve every placement');
    assert.equal(actual.placements.length, 9);
    assert.ok(actual.placements.some(p => p.shape.offsets.has(-1)), 'explicit card halves are retained');
    assert.ok(actual.placements.some(p => !p.shape.offsets.has(-1)), 'missing metadata uses extents fallback');
  }
});

test('fan arrow witnesses reacquire obstacle zero after other moving-ray certificates miss', () => {
  const overrides = {spread: false, facing: 0, span: 0.5};
  const clean = sameFan(9, overrides);
  const rays = clean.placements.map(p => {
    const half = p.shape.offsets.get(-1);
    return {x: p.x + (p.side === 0 ? -half.x : p.side === 2 ? half.x : 0),
      y: p.y + (p.side === 1 ? -half.y : p.side === 3 ? half.y : 0)};
  });
  const blockers = rays.map(p => box(p.x / 2, p.y / 2, 4, 4));
  const hit = (ray, obstacle) => segmentHitsBox(0, 0, ray.x, ray.y,
    obstacle.left - 10, obstacle.top - 10, obstacle.right + 10, obstacle.bottom + 10);
  const first = 0, other = rays.findIndex((ray, i) => i !== first &&
    !hit(ray, blockers[first]) && !hit(rays[first], blockers[i]));
  assert.notEqual(other, -1, 'the fixture has separated rays with distinct exact blockers');
  assert.equal(hit(rays[first], blockers[first]), true);
  assert.equal(hit(rays[other], blockers[other]), true);
  const far = Array.from({length: 24}, (_, i) => box(-18000 + i * 600, -12000, 40, 20));
  const unsafe = {left: NaN, right: 50, top: -10, bottom: 10};
  for (const boxes of [
    [blockers[first], blockers[other], ...far], [blockers[other], blockers[first], ...far],
    [far[0], blockers[first], blockers[other], ...far.slice(1)],
    [blockers[first], blockers[other], unsafe, ...far],
    [blockers[first]], [],
  ]) {
    for (const shadows of [false, true]) {
      sameFan(9, {...overrides, obstacles: {boxes, segments: [], shadows}});
    }
  }
});

test('fan arrow expanded boxes preserve first, witness and tree clips at exact boundaries', () => {
  const overrides = {spread: false, facing: 0, span: 0.5};
  const clean = sameFan(9, overrides), first = clean.placements[0];
  const half = first.shape.offsets.get(-1);
  const px = first.x + (first.side === 0 ? -half.x : first.side === 2 ? half.x : 0);
  const py = first.y + (first.side === 1 ? -half.y : first.side === 3 ? half.y : 0);
  const far = Array.from({length: 24}, (_, i) => box(-18000 + i * 600, -12000, 40, 20));
  const blockers = clean.placements.slice(0, 3).map(p => box(p.x / 2, p.y / 2, 4, 4));
  for (const delta of [-1e-10, 0, 1e-10]) {
    const x = (px >= 0 ? -1 : 1) * (10 + delta);
    const y = (py >= 0 ? -1 : 1) * (10 + delta);
    const tangent = {left: x, right: x, top: y, bottom: y};
    assert.equal(segmentHitsBox(0, 0, px, py, x - 10, y - 10, x + 10, y + 10), delta <= 0,
      'the exact ten-unit expansion distinguishes origin tangency from separation');
    for (const boxes of [[tangent, ...far], [far[0], ...blockers, tangent, ...far.slice(1)]]) {
      sameFan(9, {...overrides, obstacles: {boxes, segments: [], shadows: false}});
    }
  }
  // Unsafe/nonfinite expanded arithmetic and very large finite boxes retain the original exact scan fallback.
  for (const unusual of [
    {left: 2 ** 80, right: 2 ** 80 + 2 ** 30, top: -(2 ** 60), bottom: 2 ** 60},
    {left: -Infinity, right: Infinity, top: -1, bottom: 1},
    {left: NaN, right: 50, top: -10, bottom: 10},
    {left: 400, right: 200, top: -50, bottom: 50},
  ]) {
    sameFan(9, {...overrides, obstacles: {boxes: [far[0], unusual, ...blockers, ...far.slice(1)],
      segments: [], shadows: false}});
  }
});

test('fan collision witnesses preserve moving hit-clear-hit trials and relaxed retries', () => {
  const overrides = {spread: false, facing: 0, span: 0.5};
  const clean = sameFan(9, overrides);
  const blockers = clean.placements.slice(0, 3).map(p => box(p.x, p.y, 80, 16));
  const areas = clean.placements.slice(4, 6).map(p => box(p.x, p.y, 80, 12));
  for (const boxes of [blockers, blockers.slice().reverse()]) {
    for (const shadows of [true, false]) {
      // Box zero always misses. Separated blockers require the ring walk to leave one collision and encounter
      // another as it advances by ALONG_STEP, so a previous witness must be revalidated rather than cached true.
      const fan = sameFan(9, {...overrides, obstacles: {
        boxes: [box(-20000, -20000), ...boxes], areas, segments: [], shadows,
      }});
      assert.notDeepEqual(orderedFan(fan), orderedFan(clean), 'obstacle hits affect the selected placement');
    }
  }
});

test('fan arrow crossings retain strict orientation results for endpoints, parallel and nonfinite arithmetic', () => {
  const overrides = {spread: false, facing: 0};
  const clean = sameFan(1, overrides), first = clean.placements[0], e = first.shape.extents;
  const unitBounds = [first.x - e.left - 10, first.y - e.top - 10,
    first.x + e.right + 10, first.y + e.bottom + 10];
  const variants = [
    [150, -100, 150, 100], [150, 0, 150, 100], [50, 50, 160, 50], [50, 1e-13, 160, 1e-13],
    [150, -Number.MAX_VALUE, 150, Number.MAX_VALUE], [150, -Infinity, 150, Infinity],
    [150, NaN, 150, 100], [150, -0, 150, 0], [150, -Number.MIN_VALUE, 150, Number.MIN_VALUE],
  ];
  for (const segment of variants) {
    assert.equal(segmentHitsBox(...segment, ...unitBounds), false, 'the unit clip misses so arrow crossing is reached');
    for (const endpoints of [segment, [segment[2], segment[3], segment[0], segment[1]]]) {
      const fan = sameFan(1, {...overrides, obstacles: {boxes: [], segments: [endpoints], shadows: false}});
      if (segment === variants[0]) {
        assert.notDeepEqual(orderedFan(fan), orderedFan(clean), 'a strict crossing changes the selected fan');
      }
      if (segment === variants[1]) {
        assert.deepEqual(orderedFan(fan), orderedFan(clean), 'touching only a segment endpoint remains clear');
      }
    }
  }
});

test('fan crossing witnesses are revalidated as consecutive rays leave one segment and meet another', () => {
  const overrides = {spread: false, facing: 0, span: 0.5};
  const clean = sameFan(9, overrides);
  const blockers = clean.placements.slice(0, 3).map(p => {
    const half = p.shape.offsets.get(-1);
    const px = p.x + (p.side === 0 ? -half.x : p.side === 2 ? half.x : 0);
    const py = p.y + (p.side === 1 ? -half.y : p.side === 3 ? half.y : 0);
    const length = Math.hypot(px, py), dx = -py / length * 24, dy = px / length * 24;
    const segment = [px / 2 - dx, py / 2 - dy, px / 2 + dx, py / 2 + dy];
    const e = p.shape.extents;
    assert.equal(segmentHitsBox(...segment, p.x - e.left - 10, p.y - e.top - 10,
      p.x + e.right + 10, p.y + e.bottom + 10), false, 'the corresponding unit clears its arrow blocker');
    return segment;
  });
  for (const segments of [blockers, blockers.slice().reverse()]) {
    for (const shadows of [false, true]) {
      const fan = sameFan(9, {...overrides, obstacles: {
        boxes: [], segments: [[-20000, -20000, -19000, -19000], ...segments], shadows,
      }});
      if (!shadows) assert.notDeepEqual(orderedFan(fan), orderedFan(clean), 'crossing hits affect the selected fan');
    }
  }
});

test('unit segment witnesses reacquire zero after a different collision certificate misses', () => {
  const overrides = {spread: false, facing: 0, span: 0.5};
  const clean = sameFan(9, overrides);
  const bounds = clean.placements.map(p => [p.x - p.shape.extents.left - 10, p.y - p.shape.extents.top - 10,
    p.x + p.shape.extents.right + 10, p.y + p.shape.extents.bottom + 10]);
  const blockers = clean.placements.map(p => [p.x - p.shape.extents.left - 20, p.y,
    p.x + p.shape.extents.right + 20, p.y]);
  const first = 0, other = bounds.findIndex((query, i) => i !== first &&
    !segmentHitsBox(...blockers[first], ...query) && !segmentHitsBox(...blockers[i], ...bounds[first]));
  assert.notEqual(other, -1, 'distinct unit boxes have mutually separated exact blockers');
  assert.equal(segmentHitsBox(...blockers[first], ...bounds[first]), true);
  assert.equal(segmentHitsBox(...blockers[other], ...bounds[other]), true);
  const far = [-20000, -20000, -19000, -19000];
  for (const segments of [
    [blockers[first], blockers[other], far], [blockers[other], blockers[first], far],
    [far, blockers[first], blockers[other]],
    [blockers[first], blockers[other], [-Number.MAX_VALUE, 0, Number.MAX_VALUE, 1]],
    [blockers[first], blockers[other], [NaN, 0, NaN, 1]], [blockers[first]], [],
  ]) {
    for (const shadows of [true, false]) sameFan(9, {...overrides, obstacles: {boxes: [], segments, shadows}});
  }
});

test('crossing segment witnesses reacquire zero through separated rays and unsafe coordinates', () => {
  const overrides = {spread: false, facing: 0, span: 0.5};
  const clean = sameFan(9, overrides);
  const rays = clean.placements.map(p => {
    const half = p.shape.offsets.get(-1);
    return [p.x + (p.side === 0 ? -half.x : p.side === 2 ? half.x : 0),
      p.y + (p.side === 1 ? -half.y : p.side === 3 ? half.y : 0)];
  });
  const blockers = rays.map(([x, y]) => {
    const length = Math.hypot(x, y), dx = -y / length * 24, dy = x / length * 24;
    return [x / 2 - dx, y / 2 - dy, x / 2 + dx, y / 2 + dy];
  });
  const cross = ([x, y], [ax, ay, bx, by]) =>
    ((x * ay - y * ax) * (x * by - y * bx) < -1e-9) &&
    (((bx - ax) * -ay - (by - ay) * -ax) * ((bx - ax) * (y - ay) - (by - ay) * (x - ax)) < -1e-9);
  const first = 0, other = rays.findIndex((ray, i) => i !== first &&
    !cross(ray, blockers[first]) && !cross(rays[first], blockers[i]));
  assert.notEqual(other, -1, 'distinct arrow rays have mutually separated strict crossings');
  assert.equal(cross(rays[first], blockers[first]), true);
  assert.equal(cross(rays[other], blockers[other]), true);
  const far = [-20000, -20000, -19000, -19000];
  for (const segments of [
    [blockers[first], blockers[other], far], [blockers[other], blockers[first], far],
    [far, blockers[first], blockers[other]], [blockers[first], blockers[other], [Infinity, 0, Infinity, 1]],
    [blockers[first], blockers[other], [NaN, 0, NaN, 1]], [blockers[first]], [],
  ]) sameFan(9, {...overrides, obstacles: {boxes: [], segments, shadows: false}});
});

test('unit segment witnesses revalidate moving ring boxes through collision hits and misses', () => {
  const overrides = {spread: false, facing: 0, span: 0.5};
  const clean = sameFan(9, overrides);
  const bounds = clean.placements.map(p => [p.x - p.shape.extents.left - 10, p.y - p.shape.extents.top - 10,
    p.x + p.shape.extents.right + 10, p.y + p.shape.extents.bottom + 10]);
  const blockers = clean.placements.slice(0, 3).map((p, i) => {
    const segment = [p.x - p.shape.extents.left - 20, p.y, p.x + p.shape.extents.right + 20, p.y];
    assert.equal(segmentHitsBox(...segment, ...bounds[i]), true, 'each blocker certifies an actual unit collision');
    assert.ok(bounds.some(query => !segmentHitsBox(...segment, ...query)), 'the same blocker misses another unit box');
    return segment;
  });
  for (const segments of [blockers, blockers.slice().reverse()]) {
    for (const shadows of [true, false]) {
      const fan = sameFan(9, {...overrides, obstacles: {
        boxes: [], segments: [[-20000, -20000, -19000, -19000], ...segments], shadows,
      }});
      assert.notDeepEqual(orderedFan(fan), orderedFan(clean), 'unit collisions change the selected placement');
    }
  }
});

test('fan obstacle retries retain exact scan semantics for nonfinite, inverted and very large bounds', () => {
  const blocked = {
    boxes: [{left: -Infinity, right: Infinity, top: -Infinity, bottom: Infinity}],
    areas: [], segments: [], directions: [0, Math.PI / 2],
  };
  const retried = sameFan(1, {obstacles: blocked});
  assert.deepEqual(orderedFan(retried), orderedFan(placeFan(request(1))), 'relaxing directions, shadows and all obstacles preserves the final fallback');
  sameFan(3, {obstacles: {
    boxes: [box(-(2 ** 43), 2 ** 43, 2 ** 42, 2 ** 41), {left: 900, right: 800, top: -30, bottom: 40},
      {left: NaN, right: 300, top: -400, bottom: 400}],
    areas: [{left: -100, right: 100, top: Infinity, bottom: Infinity}],
    segments: [[-(2 ** 43), -(2 ** 43), 2 ** 43, 2 ** 43]], shadows: true,
  }});
  for (const spacing of [{clearX: -12, clearY: -5}, {clearX: NaN}, {clearX: 1e100}]) {
    sameFan(1, {spacing, obstacles: {boxes: [box(500, 200)], areas: [box(-500, -200)], segments: []}});
  }
});
